System.register("chunks:///_virtual/LetterData.ts",["cc"],(function(e){var r;return{setters:[function(e){r=e.cclegacy}],execute:function(){e({getCastleTimeLimit:function(e){var r=o[e];if(!r||"castle"!==r.regionId)return 0;var n=t.castle;if(!n)return 0;var i=n.letters.indexOf(e);if(i<0)return 0;var g=a.length-1,s=a[Math.min(i,g)],m=(r.text||"").split(/\s+/).filter(Boolean).length;return Math.round(m*s+l)},getRegionForLetter:function(e){var r=o[e];return r&&t[r.regionId]||null}}),r._RF.push({},"3a6085W+MNP77wTEUFnY2EO","LetterData",void 0);var t=e("REGIONS",{valley:{id:"valley",name:"Яблоневая долина",subtitle:"Здесь начинается твой путь",mapImage:"maps/area1",mapImageDark:"maps/area1_dark",letters:["А","Б","В","Г","Д"],worldMapPos:{x:.5,y:.88},themeColor:"#4ABB65"},forest:{id:"forest",name:"Грибной лес",subtitle:"Тайны фиолетовых сумерек",mapImage:"maps/area2",mapImageDark:"maps/area2_dark",letters:["Е","Ё","Ж","З","И","Й"],worldMapPos:{x:.5,y:.74},themeColor:"#8B3FBF"},mountains:{id:"mountains",name:"Тюльпановые горы",subtitle:"Над облаками",mapImage:"maps/area3",mapImageDark:"maps/area3_dark",letters:["К","Л","М","Н","О","П"],worldMapPos:{x:.52,y:.6},themeColor:"#E879A6"},shore:{id:"shore",name:"Лимонный берег",subtitle:"Где небо встречается с морем",mapImage:"maps/area4",mapImageDark:"maps/area4_dark",letters:["Р","С","Т","У","Ф"],worldMapPos:{x:.4,y:.46},themeColor:"#FFB627"},caves:{id:"caves",name:"Кристальные пещеры",subtitle:"Свет из глубины",mapImage:"maps/area5",mapImageDark:"maps/area5_dark",letters:["Х","Ц","Ч","Ш","Щ"],worldMapPos:{x:.46,y:.32},themeColor:"#3E9DC9"},castle:{id:"castle",name:"Замок Чернослова",subtitle:"Финальная битва",mapImage:"maps/area6",mapImageDark:"maps/area6_dark",letters:["Ъ","Ы","Ь","Э","Ю","Я"],worldMapPos:{x:.5,y:.17},themeColor:"#4A2C5A"}}),o=e("LETTERS",{"А":{letter:"А",regionId:"valley",mapPos:{x:.4,y:.85},world:"Яблоневая долина",worldHint:"нужна помощь с садом 🍎",text:"В саду живёт буква А. Она собирает алые яблоки в корзинку.",greeting:"Читай громко и с чувством — мой сад оживёт!",celebration:"Благодаря тебе голос вернулся! Спасибо!",primaryColor:"#FF6B5B",accentColor:"#E84D3D",bgTint:"#B85AA0"},"Б":{letter:"Б",regionId:"valley",mapPos:{x:.68,y:.68},world:"Бобровый пруд",worldHint:"плотину смыло ветром",text:"На пруду живёт буква Б. У неё белая борода и большие ботинки. Из брёвен Б строит башню, чтобы маленькие бобры играли в догонялки на её крыше.",greeting:"Помоги починить плотину — читай!",celebration:"Благодаря тебе плотина стала крепче прежней!",primaryColor:"#5BA3D9",accentColor:"#3E7DB5",bgTint:"#5BA3D9"},"В":{letter:"В",regionId:"valley",mapPos:{x:.28,y:.55},world:"Васильковое поле",worldHint:"васильки погасли без голоса",text:"В поле живёт буква В. Она вьёт венки из синих васильков и дарит их зайцам. А ветер играет с её косами и сыплет на голову жёлтые лепестки.",greeting:"Читай — и васильки снова зацветут!",celebration:"Благодаря тебе поле снова синее!",primaryColor:"#5B7DD9",accentColor:"#3E5DB5",bgTint:"#E85A3D"},"Г":{letter:"Г",regionId:"valley",mapPos:{x:.55,y:.42},world:"Грушевая роща",worldHint:"груши не зреют без слов",text:"В роще живёт буква Г. У неё громкий голос. Г говорит со своими грушами, и от её слов плоды зреют и звенят на ветру, как маленькие колокольчики.",greeting:"Читай громко — мои груши проснутся!",celebration:"Благодаря тебе груши поспели от радости!",primaryColor:"#A8D9A0",accentColor:"#7DB570",bgTint:"#8FBF5A"},"Д":{letter:"Д",regionId:"valley",mapPos:{x:.75,y:.28},world:"Домик Дятла",worldHint:"дятел потерял свой голос",text:"В домике на дубе живёт буква Д. У неё длинный клюв и добрые глаза. Каждое утро Д кормит дятла семечками с тёплой ладошки и рассказывает ему сказки.",greeting:"Верни дятлу его голос — читай!",celebration:"Благодаря тебе дятел снова стучит! Тук-тук-тук!",primaryColor:"#D9A85B",accentColor:"#B5853E",bgTint:"#D9A85B"},"Е":{letter:"Е",regionId:"forest",mapPos:{x:.2,y:.22},world:"Ельник",worldHint:"ели уснули в сумерках",text:"В тёмном лесу живёт буква Е. Она ест ежевику и дружит с енотом.",greeting:"Помоги ельнику зазвучать — читай громко!",celebration:"Благодаря тебе ельник снова шумит — спасибо!",primaryColor:"#7C5BD9",accentColor:"#5A3FB5",bgTint:"#7C5BD9"},"Ё":{letter:"Ё",regionId:"forest",mapPos:{x:.78,y:.22},world:"Ёжикина опушка",worldHint:"ёжики ёжатся от холода",text:"У ёжика на лесной опушке гостит буква Ё. Он угощает её ягодами и поит чаем с мёдом из блюдца. Когда дует холодный ветер, ёжик ёжится, а буква Ё греет его светом и тихо шепчет ему добрые слова.",greeting:"Прочитай — и ёжики снова покатятся колобками!",celebration:"Благодаря тебе ёжики весело покатились!",primaryColor:"#D9A55B",accentColor:"#B5853E",bgTint:"#D9A55B"},"Ж":{letter:"Ж",regionId:"forest",mapPos:{x:.22,y:.5},world:"Жуковый овраг",worldHint:"светлячки погасли",text:"В тёмном овраге живёт буква Ж в домике из коры. Светящиеся жуки летают вокруг и кружат, как живые искры. Буква Ж жужжит вместе с ними и зажигает фонарики на тропе, чтобы лесные звери не сбились с пути в густых сумерках.",greeting:"Зажги вместе со мной светлячков — читай!",celebration:"Благодаря тебе светлячки зажглись — лес снова светится!",primaryColor:"#A8D95B",accentColor:"#7DB540",bgTint:"#7C5BD9"},"З":{letter:"З",regionId:"forest",mapPos:{x:.55,y:.42},world:"Звёздная поляна",worldHint:"звёзды не звенят без голоса",text:"На поляне, под куполом ночного неба, тихо светится буква З. Она зовёт звёзды спуститься пониже и поиграть в траве. Звёзды звенят, как маленькие колокольчики, сыплют зелёные искры и водят хоровод вокруг буквы до самого утра.",greeting:"Позови звёзды голосом — пусть зазвенят!",celebration:"Благодаря тебе звёзды снова звенят — слышишь?",primaryColor:"#5BD9C5",accentColor:"#3FB5A5",bgTint:"#5B7DD9"},"И":{letter:"И",regionId:"forest",mapPos:{x:.8,y:.55},world:"Ивовая заводь",worldHint:"ива замерла без шёпота",text:"У заводи, где вода блестит, как зеркало, стоит буква И в венке из кувшинок. Старые ивы и синие ирисы шепчут её имя по слогам. Игривый ил искрится под ногами, а в воде играют золотые искры от букв и от лунного света.",greeting:"Разбуди иву — пусть зашелестит листвой!",celebration:"Благодаря тебе ива зашелестела — спасибо!",primaryColor:"#5B9DD9",accentColor:"#3F7DB5",bgTint:"#7C5BD9"},"Й":{letter:"Й",regionId:"forest",mapPos:{x:.45,y:.78},world:"Йотов холмик",worldHint:"холмик молчит",text:"На круглом холме живёт буква Й — самая короткая, но самая бойкая в лесу. Она прыгает с камня на камень, кувыркается в траве и не сидит на месте ни минутки. Вместе с ветром Й кричит лесу «йо-йо», и листья пляшут вокруг неё в ответ.",greeting:"Пусть мой холм зазвенит — читай громко и с задором!",celebration:"Благодаря тебе холм звенит — лес ожил!",primaryColor:"#D95B9D",accentColor:"#B53F80",bgTint:"#D95B9D"},"К":{letter:"К",regionId:"mountains",mapPos:{x:.25,y:.18},world:"Кроличья гора",worldHint:"кролики разбрелись",text:"На горе живёт буква К. Пушистые кролики катают камешки и слушают сказки.",greeting:"Покрути со мной кроличью карусель — читай!",celebration:"Благодаря тебе кролики снова кружат — спасибо!",primaryColor:"#FFA8C8",accentColor:"#E87DA8",bgTint:"#E879A6"},"Л":{letter:"Л",regionId:"mountains",mapPos:{x:.78,y:.2},world:"Льдинистая вершина",worldHint:"снежинки погасли",text:"На вершине, выше всех облаков, в избушке из льда живёт буква Л. Она ловит снежинки тёплыми ладонями и лепит из них летучие лодочки. Потом она отпускает их плыть по ветру в небо. Лёгкий ветер ласкает её косы и шепчет: «Лалала, лалала», а эхо разносит шёпот по всем горам.",greeting:"Слепи со мной лунные лодочки — читай!",celebration:"Благодаря тебе небо снова светится!",primaryColor:"#A8C5FF",accentColor:"#7DA0E8",bgTint:"#A8C5FF"},"М":{letter:"М",regionId:"mountains",mapPos:{x:.22,y:.45},world:"Маковый склон",worldHint:"маки замерли",text:"На склоне, где земля красная от лепестков, живёт буква М в шалаше из стеблей. Маленькие маки качают яркими головками и здороваются друг с другом по утрам. Буква М мажет их лепестки сладким нектаром, чтобы они блестели на солнце. А мохнатая муха помогает ей и тихо мурчит своё «м-м-м», как полосатая пчёлка в полёте.",greeting:"Помоги мне — пусть мак расцветёт от голоса!",celebration:"Благодаря тебе маки распустились!",primaryColor:"#FF6B7D",accentColor:"#E84D60",bgTint:"#E84D60"},"Н":{letter:"Н",regionId:"mountains",mapPos:{x:.55,y:.42},world:"Небесная гряда",worldHint:"облака разучились говорить",text:"На небесной гряде, у самого края обрыва, в домике из облачного пуха живёт буква Н. Она глядит на облака и даёт каждому имя: Низенький, Носатый, Невидимка и ленивый Непоседа. Когда наступает ночь, облака подплывают поближе, подставляют свои мягкие спины и несут букву Н над спящими горами до самого рассвета.",greeting:"Назови со мной облака — читай!",celebration:"Благодаря тебе облака заговорили!",primaryColor:"#D9A8FF",accentColor:"#B580E8",bgTint:"#B580E8"},"О":{letter:"О",regionId:"mountains",mapPos:{x:.5,y:.62},world:"Облачное озеро",worldHint:"орлы улетели в тишину",text:"У горного озера, в которое смотрят облака, сидит буква О на круглом камне. Она бросает в воду гладкие камешки, и от них расходятся круги — один за другим, до самого дальнего берега. А орлы в небе тихо облетают её, машут большими крыльями и охают: «Оо-оо!», как добрые соседи.",greeting:"Позови орлов — пусть кружат над озером!",celebration:"Благодаря тебе орлы вернулись!",primaryColor:"#FFB627",accentColor:"#E89D0A",bgTint:"#FFB627"},"П":{letter:"П",regionId:"mountains",mapPos:{x:.78,y:.72},world:"Перевал тюльпанов",worldHint:"тюльпаны не пахнут",text:"На перевале, между двух розовых вершин, в полосатом домике с круглой трубой живёт буква П. Каждое утро она поливает розовые тюльпаны из маленькой лейки и приговаривает: «Пум-па-па, пум-па-па». Полевые пчёлы прилетают её послушать, а потом приносят в подарок золотую пыльцу и пушистые лепестки клевера.",greeting:"Прочитай со мной слова тюльпанов!",celebration:"Благодаря тебе тюльпаны зацвели!",primaryColor:"#FF8B5B",accentColor:"#E86B3D",bgTint:"#E86B3D"},"Р":{letter:"Р",regionId:"shore",mapPos:{x:.22,y:.22},world:"Радужный риф",worldHint:"риф потерял краски",text:"У рифа живёт Р. Рыбы поют. Кораллы цветут. Риф снова сияет.",greeting:"Раскрась риф голосом — читай громко и звонко!",celebration:"Благодаря тебе риф снова сияет — спасибо!",primaryColor:"#FF7B5B",accentColor:"#E85D3D",bgTint:"#E85D3D"},"С":{letter:"С",regionId:"shore",mapPos:{x:.78,y:.22},world:"Солнечная коса",worldHint:"солнце спряталось за тучи",text:"На песчаной косе, где волны ласкают берег, стоит буква С в соломенной шляпке. Она собирает в ладонь тёплые солнечные зайчики и складывает их в плетёную корзинку. Серебряные сардинки выпрыгивают из моря и смеются, а старый седой краб уважительно щёлкает клешнями ей навстречу.",greeting:"Позови солнце — пусть выглянет из-за туч!",celebration:"Благодаря тебе солнце снова светит над косой!",primaryColor:"#FFD15B",accentColor:"#E8B03D",bgTint:"#FFB627"},"Т":{letter:"Т",regionId:"shore",mapPos:{x:.32,y:.48},world:"Тихая бухта",worldHint:"тюлени тоскуют без песен",text:"В тихой бухте, где над водой летают чайки, живёт буква Т в домике на тонких сваях. Она тянет тяжёлые сети с серебряной рыбой и тихо напевает старинную морскую песенку. Толстые тюлени высовывают усатые мордочки из воды и подпевают: «Ту-ту-ту!», как маленький оркестр.",greeting:"Тяни длинно гласные — пусть тюлени запоют с тобой!",celebration:"Благодаря тебе бухта поёт на разные голоса!",primaryColor:"#5BBFD9",accentColor:"#3F9DB5",bgTint:"#5BBFD9"},"У":{letter:"У",regionId:"shore",mapPos:{x:.72,y:.55},world:"Утиная заводь",worldHint:"утки забыли свои имена",text:"В заводи, где вода спокойна, как зеркало, живёт буква У в лодочке из камыша. Утром она угощает уток тёплым хлебом из берестяной чашки и зовёт каждую по имени. Утки отвечают дружным «у-у-у», как тёплое эхо в трубе, и плывут за лодочкой по тихой воде до самого вечера.",greeting:"Уу-у — позови уток вместе со мной!",celebration:"Благодаря тебе утки снова откликаются — слышишь?",primaryColor:"#9DD95B",accentColor:"#7DB540",bgTint:"#9DD95B"},"Ф":{letter:"Ф",regionId:"shore",mapPos:{x:.5,y:.78},world:"Фонарный мыс",worldHint:"маяк погас в тумане",text:"На самом высоком мысе стоит маяк, а в нём живёт буква Ф в синем плаще с серебряными пуговицами. Каждый вечер она зажигает большой фонарь и направляет тёплый луч в туман над морем. Фрегаты с алыми парусами видят свет издалека и плывут к берегу, а буква Ф приветливо машет им рукавом, как старым друзьям.",greeting:"Зажги маяк голосом — читай ровно и ярко!",celebration:"Благодаря тебе маяк снова светит — корабли вернулись!",primaryColor:"#A87DD9",accentColor:"#805AB5",bgTint:"#A87DD9"},"Х":{letter:"Х",regionId:"caves",mapPos:{x:.22,y:.28},world:"Хрустальный грот",worldHint:"хрусталь молчит без эха",text:"В тёмном гроте живёт буква Х. Она хранит хрустальные шары на подушках.",segments:["В тёмном гроте живёт буква Х.","Она хранит хрустальные шары на подушках."],greeting:"Прочитай по порядку — пусть эхо повторит каждый шар!",celebration:"Благодаря тебе хрусталь зазвенел — слышишь эхо?",primaryColor:"#7BD9F0",accentColor:"#3E9DC9",bgTint:"#3E9DC9"},"Ц":{letter:"Ц",regionId:"caves",mapPos:{x:.78,y:.28},world:"Цветной кристалл",worldHint:"цветы из кристалла не цветут",text:"У цветного кристалла, в самой светлой пещере под высокими сводами, сидит буква Ц на резной табуретке из лунного камня. Целыми днями она целится тонким тёплым лучом света в спящие самоцветы и согревает их своим тихим светом. От её ласкового луча цветок-кристалл медленно раскрывает острые лепестки, цветёт всеми оттенками сирени и тихо цокает, словно благодарит букву за тепло и заботу.",segments:["У цветного кристалла, в самой светлой пещере под высокими сводами,","сидит буква Ц на резной табуретке из лунного камня.","Целыми днями она целится тонким тёплым лучом света в спящие самоцветы","и согревает их своим тихим светом.","От её ласкового луча цветок-кристалл медленно раскрывает острые лепестки,","цветёт всеми оттенками сирени и тихо цокает,","словно благодарит букву за тепло и заботу."],greeting:"Целься голосом — пусть цветок-кристалл расцветёт!",celebration:"Благодаря тебе кристаллы цокают на разные голоса!",primaryColor:"#D9A0F0",accentColor:"#A05ACC",bgTint:"#A05ACC"},"Ч":{letter:"Ч",regionId:"caves",mapPos:{x:.2,y:.55},world:"Чистый ручей",worldHint:"ручей застыл без слов",text:"У чистого ручья, что бежит по дну пещеры между мшистыми камнями, живёт буква Ч в домике из ракушек. Она часто садится на мокрый берег и чертит на воде тонкие чёрточки своей лёгкой палочкой. От палочки по воде расходятся круги, а мелкие чешуйки тихо мерцают между камешками и блестят в тёмной воде, как далёкие звёздочки на небе.",segments:["У чистого ручья, что бежит по дну пещеры между мшистыми камнями,","живёт буква Ч в домике из ракушек.","Она часто садится на мокрый берег","и чертит на воде тонкие чёрточки своей лёгкой палочкой.","От палочки по воде расходятся круги,","а мелкие чешуйки тихо мерцают между камешками","и блестят в тёмной воде, как далёкие звёздочки на небе."],greeting:"Читай не торопясь — ручей подхватит каждое слово!",celebration:"Благодаря тебе ручей зажурчал — спасибо!",primaryColor:"#5BD9C5",accentColor:"#3FB5A5",bgTint:"#3FB5A5"},"Ш":{letter:"Ш",regionId:"caves",mapPos:{x:.78,y:.55},world:"Шуршащая шахта",worldHint:"шорохи замолкли",text:"В шуршащей шахте, среди узких коридоров и старых лестниц, живёт буква Ш в шёлковом платке и серебряных туфельках. Шесть шустрых шиншилл с серебристой шерстью бегают у её ног и щекочут её мягкими хвостами, выпрашивая орешки. А шёлковые шарики весело шуршат и подскакивают по гладкому полу, как живая ртуть, и сыплют звонкими брызгами по всем закоулкам.",segments:["В шуршащей шахте, среди узких коридоров и старых лестниц,","живёт буква Ш в шёлковом платке и серебряных туфельках.","Шесть шустрых шиншилл с серебристой шерстью бегают у её ног","и щекочут её мягкими хвостами, выпрашивая орешки.","А шёлковые шарики весело шуршат и подскакивают по гладкому полу,","как живая ртуть, и сыплют звонкими брызгами по всем закоулкам."],greeting:"Шепни шахте — пусть шорохи вернутся!",celebration:"Благодаря тебе в шахте снова шуршит и шепчет!",primaryColor:"#FFA8C8",accentColor:"#E87DA8",bgTint:"#E87DA8"},"Щ":{letter:"Щ",regionId:"caves",mapPos:{x:.5,y:.78},world:"Щебневая впадина",worldHint:"щёлкающие камешки уснули",text:"В щебневой впадине, на самом дне глубокого колодца, прячется буква Щ среди разноцветных осколков и старых пуговиц. Часами она щёлкает мелкими камешками друг о дружку, как щёткой по гладкой доске, и из-под её рук во все стороны летят золотые искры. А маленький щенок-кристаллик подбегает к ней и щекочет её щепоткой холодных серебряных искр, отчего она звонко смеётся.",segments:["В щебневой впадине, на самом дне глубокого колодца,","прячется буква Щ среди разноцветных осколков и старых пуговиц.","Часами она щёлкает мелкими камешками друг о дружку,","как щёткой по гладкой доске,","и из-под её рук во все стороны летят золотые искры.","А маленький щенок-кристаллик подбегает к ней","и щекочет её щепоткой холодных серебряных искр, отчего она звонко смеётся."],greeting:"Прочти по очереди — щёлкнем камешками вместе!",celebration:"Благодаря тебе щебень снова щёлкает — слышишь?",primaryColor:"#7C9DD9",accentColor:"#5A7DB5",bgTint:"#5A7DB5"},"Ъ":{letter:"Ъ",regionId:"castle",mapPos:{x:.22,y:.78},world:"Подъездный мост",worldHint:"мост скован молчанием",text:"У самого моста, где тропа подъезжает к воротам, прячется буква Твёрдый знак за большим серым валуном. Она тихо помогает путникам подняться по крутой ступеньке и не упустить с плеч свои тёплые узелки. Каждому она объясняет, как правильно подъехать к воротам замка, чтобы стража их распахнула, а старый мост не заскрипел и не вздрогнул под ногами.",segments:["У самого моста, где тропа подъезжает к воротам,","прячется буква Твёрдый знак за большим серым валуном.","Она тихо помогает путникам подняться по крутой ступеньке","и не упустить с плеч свои тёплые узелки.","Каждому она объясняет, как правильно подъехать к воротам замка,","чтобы стража их распахнула,","а старый мост не заскрипел и не вздрогнул под ногами."],greeting:"Прочитай по кусочкам — ворота откроются!",celebration:"Благодаря тебе ворота скрипнули и распахнулись!",primaryColor:"#A87DD9",accentColor:"#805AB5",bgTint:"#5A3FB5"},"Ы":{letter:"Ы",regionId:"castle",mapPos:{x:.78,y:.78},world:"Дымный овраг",worldHint:"дым стелется без слов",text:"В овраге у самой скалы, где над землёй стелется седой дым, спряталась буква Ы. Она держит в руках маленький фонарик и подсвечивает путникам узкую тропу, чтобы они не сбились в густом тумане. Тёплый дым плывёт волнами и тихо рассыпается у её ног, как пушистый зверь, а где-то далеко плачет одинокая выпь и зовёт своих родных.",segments:["В овраге у самой скалы, где над землёй стелется седой дым,","спряталась буква Ы.","Она держит в руках маленький фонарик","и подсвечивает путникам узкую тропу,","чтобы они не сбились в густом тумане.","Тёплый дым плывёт волнами и тихо рассыпается у её ног,","как пушистый зверь,","а где-то далеко плачет одинокая выпь и зовёт своих родных."],greeting:"Читай ровно — пусть дым рассеется!",celebration:"Благодаря тебе дым растаял и в овраге стало светло!",primaryColor:"#7C5BD9",accentColor:"#5A3FB5",bgTint:"#7C5BD9"},"Ь":{letter:"Ь",regionId:"castle",mapPos:{x:.48,y:.62},world:"Тёмная аллея",worldHint:"тени застыли вдоль тропы",text:"На тёмной аллее, что вьётся к самой башне, тихо ступает буква Мягкий знак в мягких бархатных туфельках. Она знает все секреты теней и умеет смягчить любой острый угол одним только нежным прикосновением ладони. Если кто-то идёт к замку с дрожью в сердце, буква Мягкий знак берёт его за руку, ведёт по тёмному коридору и тихо шепчет добрые слова, пока страх не отпустит совсем.",segments:["На тёмной аллее, что вьётся к самой башне,","тихо ступает буква Мягкий знак в мягких бархатных туфельках.","Она знает все секреты теней","и умеет смягчить любой острый угол","одним только нежным прикосновением ладони.","Если кто-то идёт к замку с дрожью в сердце,","буква Мягкий знак берёт его за руку, ведёт по тёмному коридору","и тихо шепчет добрые слова, пока страх не отпустит совсем."],greeting:"Читай мягко — пусть тени отступят!",celebration:"Благодаря тебе тени отступили и аллея засветилась!",primaryColor:"#D9A0F0",accentColor:"#A05ACC",bgTint:"#A05ACC"},"Э":{letter:"Э",regionId:"castle",mapPos:{x:.18,y:.46},world:"Эхо башни",worldHint:"эхо потеряло голос",text:"У восточной башни, среди старых каменных арок и узких окошек, живёт буква Э в круглой комнатке с медным колоколом. Каждое утро она звонит в колокол и слушает, как эхо с радостным «эй» откатывается от каменных стен и улетает в тёмное небо. Эхо всегда возвращается к ней с подарком: то с песенкой ветра, то с тёплым приветом от букв из дальних регионов огромной Букварии.",segments:["У восточной башни, среди старых каменных арок и узких окошек,","живёт буква Э в круглой комнатке с медным колоколом.","Каждое утро она звонит в колокол","и слушает, как эхо с радостным «эй» откатывается от каменных стен","и улетает в тёмное небо.","Эхо всегда возвращается к ней с подарком:","то с песенкой ветра, то с тёплым приветом","от букв из дальних регионов огромной Букварии."],greeting:"Позови эхо голосом — пусть отзовётся!",celebration:"Благодаря тебе эхо снова летает над башней!",primaryColor:"#7BD9F0",accentColor:"#3E9DC9",bgTint:"#3E9DC9"},"Ю":{letter:"Ю",regionId:"castle",mapPos:{x:.82,y:.46},world:"Южная галерея",worldHint:"юный сад в галерее уснул",text:"В южной галерее замка, где сквозь высокие окна льётся прохладный лунный свет, живёт буква Ю в светлом плаще с серебряным узором. Она ухаживает за маленьким садом из юрких лиан и юных побегов и каждый росток зовёт по имени. Юркая ласточка свила гнездо под высоким сводом и каждое утро тихо поёт букве Ю свою короткую утреннюю песенку.",segments:["В южной галерее замка, где сквозь высокие окна льётся прохладный лунный свет,","живёт буква Ю в светлом плаще с серебряным узором.","Она ухаживает за маленьким садом из юрких лиан и юных побегов","и каждый росток зовёт по имени.","Юркая ласточка свила гнездо под высоким сводом","и каждое утро тихо поёт букве Ю свою короткую утреннюю песенку."],greeting:"Читай ласково — сад в галерее проснётся!",celebration:"Благодаря тебе сад в галерее снова цветёт!",primaryColor:"#FFA8C8",accentColor:"#E87DA8",bgTint:"#E87DA8"},"Я":{letter:"Я",regionId:"castle",mapPos:{x:.5,y:.3},world:"Тронный зал",worldHint:"трон молчит без последней буквы",text:"В тронном зале, у самого высокого окна, сидит буква Я в ярком плаще цвета спелого яблока. Она хранит ясный янтарный свет в маленьком фонарике и держит его близко к сердцу, как самую большую драгоценность. Когда все буквы Букварии собираются вместе, ясный свет от фонарика буквы Я разгорается ярче и согревает каждое слово, каждый звук и каждый голос на много шагов вокруг.",segments:["В тронном зале, у самого высокого окна,","сидит буква Я в ярком плаще цвета спелого яблока.","Она хранит ясный янтарный свет в маленьком фонарике","и держит его близко к сердцу,","как самую большую драгоценность.","Когда все буквы Букварии собираются вместе,","ясный свет от фонарика буквы Я разгорается ярче","и согревает каждое слово, каждый звук и каждый голос","на много шагов вокруг."],greeting:"Читай ярко — пусть янтарный свет загорится!",celebration:"Благодаря тебе тронный зал снова сияет!",primaryColor:"#FFB627",accentColor:"#E89D0A",bgTint:"#FFB627",aliases:{"Букварии":["болгарии","буквари","буквария","бухари","бухарии","букварий","буквари́и"]}}});e("ALPHABET","АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ".split(""));var a=e("CASTLE_TIMER_SEC_PER_WORD",[.95,.82,.72,.62,.54,.48]),l=e("CASTLE_TIMER_ENTRY_BUFFER",2);r._RF.pop()}}}));

